def translate(text):
    return " ".join(_translate_word(word) for word in text.split(" "))


def _translate_word(word):
    vowels = "aeiou"

    # Rule 1: starts with a vowel, "xr", or "yt"
    if word[0] in vowels or word.startswith(("xr", "yt")):
        return word + "ay"

    # Find where the consonant cluster ends: the first vowel,
    # or a "qu" after consonants (rule 3), or a "y" after consonants (rule 4).
    for i, letter in enumerate(word):
        if letter in vowels:
            break
        if letter == "q" and word[i + 1 : i + 2] == "u":
            i += 1
            break
        if letter == "y" and i > 0:
            break
    else:
        i = len(word) - 1

    return word[i + 1 :] + word[: i + 1] + "ay"

